import os
import base64
from typing import Any, Dict, List, Optional

from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.core.credentials import AzureKeyCredential


def _read_document_bytes(source: Any) -> bytes:
    if isinstance(source, (bytes, bytearray)):
        return bytes(source)
    if hasattr(source, "read"):
        data = source.read()
        return data if isinstance(data, bytes) else data.encode("utf-8")
    if isinstance(source, str):
        if source.startswith("http://") or source.startswith("https://"):
            import urllib.request

            with urllib.request.urlopen(source) as resp:
                return resp.read()
        with open(source, "rb") as f:
            return f.read()
    raise TypeError("source must be bytes, a file-like object, a local file path, or a URL")


def _normalize_line_items(result: Any) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    for line in getattr(result, "items", []) or []:
        line_dict: Dict[str, Any] = {}
        for attr_name in ("description", "quantity", "unit", "unitPrice", "productCode", "tax", "amount", "totalPrice"):
            field = getattr(line, attr_name, None)
            if field is not None and getattr(field, "value", None) is not None:
                key = "unit_price" if attr_name == "unitPrice" else attr_name
                line_dict[key] = field.value
            elif field is not None and getattr(field, "content", None) is not None:
                key = "unit_price" if attr_name == "unitPrice" else attr_name
                line_dict[key] = field.content
        if line_dict:
            items.append(line_dict)
    return items


def extract_invoice_fields(source: Any) -> Dict[str, Any]:
    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))
    document_bytes = _read_document_bytes(source)

    poller = client.begin_analyze_document(
        model_id="prebuilt-invoice",
        body=document_bytes,
        content_type="application/pdf" if document_bytes[:4] == b"%PDF" else "application/octet-stream",
    )
    result = poller.result()

    doc = (result.documents or [None])[0]
    fields = getattr(doc, "fields", {}) if doc else {}

    def get_field_value(name: str) -> Optional[Any]:
        field = fields.get(name) if isinstance(fields, dict) else None
        if field is None:
            return None
        return getattr(field, "value", None) if getattr(field, "value", None) is not None else getattr(field, "content", None)

    vendor = get_field_value("VendorName")
    if vendor is None:
        vendor = get_field_value("MerchantName")

    date = get_field_value("InvoiceDate")
    if date is None:
        date = get_field_value("ServiceStartDate")

    total = get_field_value("InvoiceTotal")
    if total is None:
        total = get_field_value("AmountDue")

    line_items = _normalize_line_items(doc) if doc else []

    return {
        "vendor": vendor,
        "date": date,
        "total": total,
        "line_items": line_items,
    }
